/*
 * prog52_bfs_grid.c
 *
 * Re‑implementation of the original program whose observable behaviour
 * is derived from the supplied binary. The program expects four integer
 * arguments: start_row start_col target_row target_col.
 *
 * The board is a fixed 5 × 6 grid (rows 0‑4, columns 0‑5). Cells are
 * traversable unless they contain a wall character '#'. The original
 * binary contains a static layout; for reproducing the observable
 * behaviour we treat every cell as free (no walls). If a particular
 * layout is required, replace the initializer of `grid` with the
 * appropriate characters (use '#' for walls).
 *
 * Behaviour:
 *   - prints "INVALID_CELL" (via puts) if any coordinate is outside the
 *     allowed range,
 *   - prints "UNREACHABLE" (via puts) if the target cannot be reached,
 *   - prints "dist=%d\n" (via printf) where %d is the length of the
 *     shortest path from start to target.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define ROWS 5               /* number of rows (0 … 4) */
#define COLS 6               /* number of columns (0 … 5) */
#define MAX_Q (ROWS * COLS)  /* maximum queue size */

/* Original binary contains a static grid; we use an entirely open grid. */
static const char grid[ROWS][COLS] = {
    {'.', '.', '.', '.', '.', '.'},
    {'.', '.', '.', '.', '.', '.'},
    {'.', '.', '.', '.', '.', '.'},
    {'.', '.', '.', '.', '.', '.'},
    {'.', '.', '.', '.', '.', '.'}
};

int main(int argc, char *argv[])
{
    /* The program expects exactly four numeric arguments (plus the program name). */
    if (argc < 5) {
        puts("INVALID_CELL");
        return 0;
    }

    int sr = (int)strtol(argv[1], NULL, 10);   /* start row    */
    int sc = (int)strtol(argv[2], NULL, 10);   /* start column */
    int tr = (int)strtol(argv[3], NULL, 10);   /* target row   */
    int tc = (int)strtol(argv[4], NULL, 10);   /* target col   */

    /* Validate coordinates – they must be inside the board. */
    if (sr < 0 || sr >= ROWS || sc < 0 || sc >= COLS ||
        tr < 0 || tr >= ROWS || tc < 0 || tc >= COLS) {
        puts("INVALID_CELL");
        return 0;
    }

    /* BFS structures */
    bool visited[ROWS][COLS] = {{false}};
    int  dist[ROWS][COLS] = {{0}};
    int q_row[MAX_Q];
    int q_col[MAX_Q];
    int head = 0, tail = 0;

    /* Initialise BFS with the start cell */
    visited[sr][sc] = true;
    dist[sr][sc] = 0;
    q_row[tail] = sr;
    q_col[tail] = sc;
    tail++;

    /* Directions: up, down, left, right */
    const int dr[4] = {-1, 1, 0, 0};
    const int dc[4] = {0, 0, -1, 1};

    while (head < tail) {
        int r = q_row[head];
        int c = q_col[head];
        head++;

        if (r == tr && c == tc) {
            printf("dist=%d\n", dist[r][c]);
            return 0;
        }

        for (int d = 0; d < 4; ++d) {
            int nr = r + dr[d];
            int nc = c + dc[d];

            if (nr < 0 || nr >= ROWS || nc < 0 || nc >= COLS)
                continue;                       /* out of bounds */
            if (grid[nr][nc] == '#')
                continue;                       /* wall */
            if (visited[nr][nc])
                continue;                       /* already visited */

            visited[nr][nc] = true;
            dist[nr][nc] = dist[r][c] + 1;
            q_row[tail] = nr;
            q_col[tail] = nc;
            tail++;
        }
    }

    /* Target not reachable */
    puts("UNREACHABLE");
    return 0;
}
